    this.delay = Math.max(0, Math.round((o.lookahead != null ? o.lookahead : LIMITER_LOOKAHEAD) * sampleRate));
    this.win = this.delay + 1;
    this.rel = Math.exp(-1 / (Math.max(0.001, o.release != null ? o.release : LIMITER_RELEASE) * sampleRate));
